const poll = $input.first()?.json || {};
if (poll.skipped) {
  return [];
}

const nowEpoch = Number(poll.nowEpoch || Math.floor(Date.now() / 1000));
const todayTrt = new Date((nowEpoch + 3 * 3600) * 1000).toISOString().slice(0, 10);
const botUsername = String(poll.botUsername || 'socialora_publisher_2026_bot').toLowerCase();

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.inbox)) sd.inbox = [];
if (!Array.isArray(sd.seenUpdates)) sd.seenUpdates = [];
if (!Array.isArray(sd.seenMsgKeys)) sd.seenMsgKeys = [];
if (!Array.isArray(sd.repliedTexts)) sd.repliedTexts = [];
if (!Array.isArray(sd.recentContext)) sd.recentContext = [];
sd.geminiDay = String(sd.geminiDay || '');
sd.geminiCountToday = Number(sd.geminiCountToday || 0);
sd.geminiCooldownUntil = Number(sd.geminiCooldownUntil || 0);

if (sd.geminiDay !== todayTrt) {
  sd.geminiDay = todayTrt;
  sd.geminiCountToday = 0;
}

const TOOLKIT = {
  shadowban: ['Shadowban Diagnostic', 'Check non-follower Explore / FYP reach signals before tweaking hashtags or deleting posts.', '/tools/instagram-shadowban-checker'],
  bio: ['Instagram Bio Generator', 'Create editable niche-focused bio drafts in seconds.', '/tools/instagram-bio-generator'],
  caption: ['Caption Hook Studio', 'Generate scroll-stopping opening lines and natural engagement CTAs.', '/tools/instagram-caption-generator'],
  rate: ['Sponsorship Rate Calculator', 'Estimate fair brand deal & UGC pricing including usage rights.', '/tools/instagram-sponsorship-rate-calculator'],
  ideas: ['Content Ideas Generator', 'Get 50+ tailored Reel & short-form video angles for your niche.', '/tools/instagram-content-ideas-generator'],
  photo: ['Photo Studio', 'Resize your image for Instagram, Stories, TikTok or YouTube.', '/tools/social-media-photo-resizer'],
  blur: ['No-Crop Photo', 'Fit a full photo into a post or Story with a soft blurred background.', '/tools/instagram-no-crop-blur-background'],
  score: ['Instagram Scorecard', 'Enter your public profile numbers to get an indicative score and a shareable card. Not official Instagram data.', '/tools/instagram-account-scorecard'],
  thumbnail: ['Video Thumbnail Studio', 'Pick a frame from your own video and export a cover image.', '/tools/video-frame-to-thumbnail'],
  safezone: ['Reels Safe Zone', 'Check where to place text so interface buttons do not cover it.', '/tools/reels-tiktok-safe-zone-guide'],
};

const extractCommand = (text) => {
  const m = String(text || '').trim().match(/^\/([a-z]+)(?:@socialora_publisher_2026_bot)?$/i);
  if (!m) return null;
  const cmd = m[1].toLowerCase();
  if (cmd === 'tools' || cmd === 'toolkit' || Object.prototype.hasOwnProperty.call(TOOLKIT, cmd)) {
    return cmd;
  }
  return null;
};

const seenUpdSet = new Set(sd.seenUpdates);
const outs = [];

// Handle owner private DM commands (/start, /growth, /status, /approve_[id], /skip_[id])
const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const escOwnerHtml = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
for (const oc of (Array.isArray(poll.ownerCommands) ? poll.ownerCommands : [])) {
  if (seenUpdSet.has(oc.update_id)) continue;
  seenUpdSet.add(oc.update_id);
  sd.seenUpdates.push(oc.update_id);

  const cmdMatch = String(oc.text || '').trim().match(/^\/(approve|skip)_([a-z0-9_-]+)(?:@[a-z0-9_]+)?$/i);
  if (cmdMatch) {
    const action = cmdMatch[1].toLowerCase();
    const targetId = cmdMatch[2];
    let respHtml = '❌ Eşleşen bekleyen Threads yanıtı bulunamadı (ID: ' + escOwnerHtml(targetId) + ').';
    try {
      const fs = require('fs');
      const nodePath = require('path');
      const full = fs.existsSync(GROWTH_PATH) ? (JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8')) || {}) : {};
      const tr = (full && typeof full.threadsReplies === 'object' && full.threadsReplies) ? full.threadsReplies : {};
      const list = Array.isArray(tr.pendingApprovals) ? tr.pendingApprovals : [];
      const row = list.find((p) => p && (String(p.approvalId) === targetId || String(p.commentId) === targetId));
      if (row) {
        if (row.status === 'published' || row.status === 'auto_published' || row.status === 'already_replied') {
          respHtml = 'ℹ️ @' + escOwnerHtml(row.commenter) + ' yorumuna yanıt zaten işlenmiş (durum: ' + escOwnerHtml(row.status) + ').';
        } else if (action === 'approve') {
          row.status = 'approved';
          row.approvedAt = nowEpoch;
          full.threadsReplies = { ...tr, pendingApprovals: list.slice(-80) };
          fs.mkdirSync(nodePath.dirname(GROWTH_PATH), { recursive: true });
          const tmp = GROWTH_PATH + '.tmp.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);
          fs.writeFileSync(tmp, JSON.stringify(full, null, 2), 'utf8');
          fs.renameSync(tmp, GROWTH_PATH);
          respHtml = '✅ <b>Onaylandı!</b>\n\n@' + escOwnerHtml(row.commenter) + ' yorumuna yanıt bir sonraki Threads kontrolünde (en geç 5 dk içinde) yayınlanacak.\n\n<b>Yanıt:</b> ' + escOwnerHtml(row.replyText);
        } else {
          row.status = 'skipped';
          row.skippedAt = nowEpoch;
          const prevReplied = Array.isArray(tr.repliedIds) ? tr.repliedIds : [];
          if (row.commentId && !prevReplied.includes(String(row.commentId))) prevReplied.push(String(row.commentId));
          full.threadsReplies = { ...tr, repliedIds: prevReplied.slice(-300), pendingApprovals: list.slice(-80) };
          fs.mkdirSync(nodePath.dirname(GROWTH_PATH), { recursive: true });
          const tmp = GROWTH_PATH + '.tmp.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);
          fs.writeFileSync(tmp, JSON.stringify(full, null, 2), 'utf8');
          fs.renameSync(tmp, GROWTH_PATH);
          respHtml = '⏭ <b>Atlandı!</b>\n\n@' + escOwnerHtml(row.commenter) + ' yorumuna yanıt gönderilmeyecek.';
        }
      }
    } catch (e) {
      respHtml = '❌ Onay dosyası güncellenemedi: ' + escOwnerHtml(e?.message || 'error');
    }
    outs.push({
      json: {
        route: 'toolkit',
        update_id: oc.update_id,
        chat_id: oc.chat_id,
        reply_to_message_id: oc.message_id,
        htmlText: respHtml,
      }
    });
    continue;
  }

  if (/^\/cockpit(?:@[a-z0-9_]+)?$/i.test(String(oc.text || '').trim())) {
    let cockpitHtml = '❌ Kokpit raporu olusturulamadi.';
    try {
      const { buildCockpitReportHtml } = require('C:\\Users\\idoca\\.n8n\\custom\\TelegramGrowth.node.js');
      const report = buildCockpitReportHtml({
        channelMembers: poll.channelMembers,
        groupMembers: poll.groupMembers,
        nowEpoch,
      });
      if (report && report.htmlText) cockpitHtml = report.htmlText;
    } catch (e) {
      cockpitHtml = '❌ Kokpit hatasi: ' + escOwnerHtml(e?.message || 'error');
    }
    outs.push({
      json: {
        route: 'toolkit',
        update_id: oc.update_id,
        chat_id: oc.chat_id,
        reply_to_message_id: oc.message_id,
        htmlText: cockpitHtml,
      }
    });
    continue;
  }

  const gs = poll.growthSummary || {};
  const snap = gs.lastSnapshot;
  const ownerHtml = [
    '<b>Socialora Telegram Yönetim Paneli</b>',
    '- Kanal: <b>' + (poll.channelMembers ?? '?') + '</b> abone | Grup: <b>' + (poll.groupMembers ?? '?') + '</b> üye',
    snap ? ('- Son 5 gönderi ortalaması: <b>' + (snap.avgLast5Views ?? 0) + ' görüntülenme</b>') : '- Büyüme radarı ilk taramasını bekliyor (tgGrowthEngine01).',
    '- Hazır ortaklık taslağı: <b>' + (gs.pendingPitches ?? 0) + '</b>',
    '',
    'Özel DM bağlantısı kuruldu. 6 saatlik büyüme raporları, ortaklık taslakları ve Threads yorum onayları otomatik buraya iletilecek.'
  ].join('\n');
  outs.push({
    json: {
      route: 'toolkit',
      update_id: oc.update_id,
      chat_id: oc.chat_id,
      reply_to_message_id: oc.message_id,
      htmlText: ownerHtml,
    }
  });
}

const groupChatId = Number(poll.groupChatId);
if (!groupChatId) {
  return outs;
}

const keywords = [
  'views', 'stuck', 'shadowban', 'reels', 'tiktok', 'instagram', 'telegram', 'youtube',
  'twitter', 'followers', 'likes', 'subscribers', 'watchtime', 'watch time', 'reach',
  'algorithm', 'price', 'pricing', 'cost', 'buy', 'order', 'refill', 'delivery', 'crypto',
  'usdt', 'btc', 'payment', 'free', 'tool', 'drop', 'calculator', 'resize', 'crop',
  'photo', 'bio', 'thumbnail', 'caption', 'safe zone', 'help', 'support', 'panel', 'service',
  'how', 'why', 'what', 'where', 'when', 'who', 'can ', 'anyone', 'admin', 'work',
  'grow', 'account', 'video', 'page', 'channel', 'trial', 'legit'
];

const isDirected = (msg, text) => {
  const t = String(text || '').trim();
  if (t.length < 3) return false;
  const lower = t.toLowerCase();
  if (extractCommand(t)) return true;
  if (lower.includes('@' + botUsername) || lower.includes('@socialoraofficial') || lower.includes('socialora')) return true;
  const replyFrom = String(msg?.reply_to_message?.from?.username || '').toLowerCase();
  const replyChat = String(msg?.reply_to_message?.sender_chat?.username || '').toLowerCase();
  if (replyFrom === botUsername) return true;
  if (['socialoraofficial', 'socialorachat'].includes(replyChat)) return true;
  if (t.includes('?')) return true;
  return t.length >= 6 && keywords.some((k) => lower.includes(k));
};

const seenKeySet = new Set(sd.seenMsgKeys);

for (const upd of (Array.isArray(poll.updates) ? poll.updates : [])) {
  if (!upd || typeof upd.update_id !== 'number') continue;
  const uid = upd.update_id;
  if (seenUpdSet.has(uid)) continue;
  seenUpdSet.add(uid);
  sd.seenUpdates.push(uid);

  const msg = upd.message;
  if (!msg || typeof msg.message_id !== 'number') continue;
  if (Number(msg.chat?.id) !== groupChatId) continue;

  const from = msg.from || {};
  const fromUser = String(from.username || '').toLowerCase();
  if (from.is_bot === true || [botUsername, 'telegram', 'channelsupportbot', 'groupanonymousbot', 'channel_bot'].includes(fromUser)) {
    continue;
  }
  if (msg.is_automatic_forward || msg.sender_chat) continue;
  const fwdChat = String(msg.forward_from_chat?.username || '').toLowerCase();
  if (['socialoraofficial', 'socialorachat'].includes(fwdChat)) continue;

  const text = String(msg.text || msg.caption || '').trim();
  if (!text || text.includes('utm_source=telegram')) continue;

  const msgKey = groupChatId + ':' + msg.message_id;
  if (seenKeySet.has(msgKey)) continue;
  seenKeySet.add(msgKey);
  sd.seenMsgKeys.push(msgKey);

  const msgDate = Number(msg.date || nowEpoch);
  if (nowEpoch - msgDate > 1800) continue;

  const sender = String(from.username || from.first_name || from.id || 'member').slice(0, 60);
  sd.recentContext.push({ sender, text: text.slice(0, 240), ts: msgDate });
  if (sd.recentContext.length > 8) sd.recentContext = sd.recentContext.slice(-8);

  const cmd = extractCommand(text);
  if (cmd) {
    try {
      const fs = require('fs');
      const nodePath = require('path');
      const full = fs.existsSync(GROWTH_PATH) ? (JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8')) || {}) : {};
      const prev = (full && typeof full.telegramTools === 'object' && full.telegramTools) ? full.telegramTools : {};
      const nextCount = (prev.dayTrt === todayTrt ? Number(prev.countToday || 0) : 0) + 1;
      full.telegramTools = { dayTrt: todayTrt, countToday: nextCount, lastCmd: cmd, lastUsedAt: nowEpoch };
      fs.mkdirSync(nodePath.dirname(GROWTH_PATH), { recursive: true });
      const tmp = GROWTH_PATH + '.tmp.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);
      fs.writeFileSync(tmp, JSON.stringify(full, null, 2), 'utf8');
      fs.renameSync(tmp, GROWTH_PATH);
    } catch {}
    const campaignId = 'reply_u' + uid;
    let bodyText;
    if (cmd === 'tools' || cmd === 'toolkit') {
      bodyText = [
        '<b>Socialora Free Creator Toolkit</b>',
        '',
        '<b>Growth &amp; Copy:</b> /shadowban, /bio, /caption, /rate, /ideas',
        '<b>Visual &amp; Framing:</b> /photo, /blur, /score, /thumbnail, /safezone',
        '',
        'Tap any command above for the instant browser tool.'
      ].join('\n');
    } else {
      const [title, advice, toolPath] = TOOLKIT[cmd];
      const href = 'https://www.getsocialora.com' + toolPath + '?utm_source=telegram&utm_medium=group&utm_campaign=' + encodeURIComponent(campaignId);
      const label = 'getsocialora.com' + toolPath;
      bodyText = '<b>' + title + '</b>: ' + advice + '\n\nOpen the free tool: <a href="' + href + '">' + label + '</a>';
      const FUNNEL_COMMANDS = new Set(['shadowban', 'bio', 'rate', 'score', 'safezone']);
      if (FUNNEL_COMMANDS.has(cmd)) {
        const trialHref = 'https://www.getsocialora.com/free-instagram-views?utm_source=telegram&utm_medium=group&utm_campaign=' + encodeURIComponent(campaignId + '_trial');
        bodyText += '\n\nTip: Testing a new Reel today? Grab your free views trial at <a href="' + trialHref + '">getsocialora.com/free-instagram-views</a>';
      }
    }
    outs.push({
      json: {
        route: 'toolkit',
        update_id: uid,
        chat_id: groupChatId,
        reply_to_message_id: msg.message_id,
        htmlText: bodyText,
      }
    });
    continue;
  }

  if (isDirected(msg, text)) {
    sd.inbox.push({
      update_id: uid,
      chat_id: groupChatId,
      message_id: msg.message_id,
      sender,
      text: text.slice(0, 1500),
      received_at: Math.min(nowEpoch, msgDate),
      status: 'pending',
      attempts: 0,
      sendingAt: 0,
    });
  }
}

if (sd.seenUpdates.length > 500) sd.seenUpdates = sd.seenUpdates.slice(-500);
if (sd.seenMsgKeys.length > 500) sd.seenMsgKeys = sd.seenMsgKeys.slice(-500);

for (const item of sd.inbox) {
  if (item.status === 'pending' && nowEpoch - item.received_at > 86400) {
    item.status = 'expired';
  } else if (item.status === 'sending' && nowEpoch - Number(item.sendingAt || 0) > 180) {
    item.status = Number(item.attempts || 0) >= 3 ? 'failed' : 'pending';
  }
}
sd.inbox = sd.inbox.filter((item) => nowEpoch - item.received_at <= 172800).slice(-120);

if (nowEpoch >= sd.geminiCooldownUntil && sd.geminiCountToday < 150) {
  const ready = sd.inbox
    .filter((item) => item.status === 'pending' && (nowEpoch - item.received_at >= 45 + (item.update_id % 45)))
    .sort((a, b) => (a.attempts - b.attempts) || (b.update_id - a.update_id));

  if (ready.length > 0) {
    const picked = ready[0];
    picked.status = 'sending';
    picked.sendingAt = nowEpoch;
    picked.attempts = Number(picked.attempts || 0) + 1;
    sd.geminiCountToday += 1;

    const ctxLines = sd.recentContext
      .filter((c) => c.ts <= picked.received_at)
      .slice(-5)
      .map((c) => c.sender + ': ' + c.text)
      .join('\n');

    const modelsCacheValid = Boolean(
      Array.isArray(sd.cachedModels) &&
      sd.cachedModels.length > 0 &&
      Number(sd.modelsCachedAt || 0) > 0 &&
      (nowEpoch - Number(sd.modelsCachedAt) < 21600)
    );

    outs.push({
      json: {
        route: 'ai',
        modelsCacheValid,
        update_id: picked.update_id,
        chat_id: picked.chat_id,
        reply_to_message_id: picked.message_id,
        sender: picked.sender,
        userText: picked.text,
        contextLines: ctxLines,
      }
    });
  }
}

return outs;

const routingNode = $('Gelen Kutusu & Yönlendirme').all();
const gItems = $input.all();
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.inbox)) sd.inbox = [];
if (!Array.isArray(sd.repliedTexts)) sd.repliedTexts = [];

const aiSource = routingNode.find((i) => i.json?.route === 'ai')?.json;
if (!aiSource) return [];

const gOut = gItems[0]?.json || {};
let raw = String(gOut?.mergedResponse ?? gOut?.candidates?.[0]?.content?.parts?.[0]?.text ?? gOut?.content?.parts?.[0]?.text ?? '').trim();
const errMsg = raw ? '' : String(gOut?.error?.message || gOut?.error?.status || gOut?.error || '');

const item = sd.inbox.find((x) => x.update_id === aiSource.update_id);

if (errMsg || raw.length < 15) {
  if (/429|quota|rate limit/i.test(errMsg)) {
    sd.geminiCooldownUntil = Math.floor(Date.now() / 1000) + 180;
  }
  if (item) {
    item.status = Number(item.attempts || 0) >= 3 ? 'failed' : 'pending';
    if (errMsg) item.lastError = errMsg.slice(0, 180);
  }
  return [];
}

const emojiRe = /[\u{1F000}-\u{1FAFF}\u2600-\u27BF\u2B00-\u2BFF\uFE0F\u200D]/gu;
let text = raw
  .replace(emojiRe, '')
  .replace(new RegExp('[*_\\x60#]+', 'g'), '')
  .replace(/\u2014/g, ',')
  .replace(/[\u2013\u2022]/g, '-')
  .replace(/!{2,}/g, '!')
  .replace(/[ \t]{2,}/g, ' ')
  .trim();

const campaignId = 'reply_u' + aiSource.update_id;

const hasSecret = /\b\d{5,}:[A-Za-z0-9_-]{20,}/.test(text);
const hasBannedGuarantee = /\b(?:100% safe|never drops|guaranteed followers)\b/i.test(text);
const asksPrivateInfo = /\b(?:send your email|share your order id|what is your order number|send payment screenshot)\b/i.test(text);
const hasTurkishChars = /[çğıöşüÇĞİÖŞÜ]/.test(text);

if (hasSecret || hasBannedGuarantee || asksPrivateInfo || hasTurkishChars || text.length < 15 || text.length > 1200) {
  if (item) item.status = Number(item.attempts || 0) >= 3 ? 'failed' : 'pending';
  return [];
}

const escHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escAttr = (s) => escHtml(s).replace(/"/g, '&quot;');
const parseSafeHttpsUrl = (rawStr) => {
  if (!/^https:\/\//i.test(rawStr)) return null;
  const rest = rawStr.slice(8);
  const cut = rest.search(/[/?#]/);
  const auth = cut === -1 ? rest : rest.slice(0, cut);
  if (!auth || auth.includes('..') || !/^[a-z0-9.-]+$/i.test(auth)) return null;
  const host = auth.toLowerCase();
  const tailAll = cut === -1 ? '' : rest.slice(cut);
  const hIdx = tailAll.indexOf('#');
  const noHash = hIdx === -1 ? tailAll : tailAll.slice(0, hIdx);
  const hash = hIdx === -1 ? '' : tailAll.slice(hIdx);
  const qIdx = noHash.indexOf('?');
  const pathRaw = qIdx === -1 ? noHash : noHash.slice(0, qIdx);
  const searchRaw = qIdx === -1 ? '' : noHash.slice(qIdx + 1);
  const pathname = pathRaw ? (pathRaw.startsWith('/') ? pathRaw : '/' + pathRaw) : '/';
  return { host, pathname, searchRaw, hash };
};
const buildSocialoraUrl = (parsed, utms) => {
  const pairs = [];
  const seen = new Set();
  if (parsed.searchRaw) {
    for (const part of parsed.searchRaw.split('&')) {
      if (!part) continue;
      const eq = part.indexOf('=');
      const k = eq === -1 ? part : part.slice(0, eq);
      const v = eq === -1 ? '' : part.slice(eq + 1);
      if (Object.prototype.hasOwnProperty.call(utms, k)) {
        if (!seen.has(k)) {
          pairs.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(utms[k])));
          seen.add(k);
        }
      } else {
        pairs.push(part);
      }
    }
  }
  for (const [k, val] of Object.entries(utms)) {
    if (!seen.has(k)) pairs.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(val)));
  }
  return 'https://www.getsocialora.com' + parsed.pathname + (pairs.length ? '?' + pairs.join('&') : '') + parsed.hash;
};

let htmlOut = '';
let plainClean = '';
let last = 0;
const urlRe = /https?:\/\/[^\s]+/g;
let m;
let urlCount = 0;

while ((m = urlRe.exec(text)) !== null) {
  const seg = text.slice(last, m.index);
  htmlOut += escHtml(seg);
  plainClean += seg;

  const rawUrl = m[0].replace(/[.,!?)]+$/, '');
  const tail = m[0].slice(rawUrl.length);
  const u = parseSafeHttpsUrl(rawUrl);
  if (u && (u.host === 'www.getsocialora.com' || u.host === 'getsocialora.com') && urlCount === 0) {
    urlCount += 1;
    const finalUrl = buildSocialoraUrl(u, {
      utm_source: 'telegram',
      utm_medium: 'group',
      utm_campaign: campaignId,
    });
    const cleanPath = u.pathname.replace(/\/+$/, '');
    const label = 'getsocialora.com' + cleanPath;
    htmlOut += '<a href="' + escAttr(finalUrl) + '">' + escHtml(label) + '</a>' + escHtml(tail);
    plainClean += finalUrl + tail;
  } else if (u && u.host === 't.me' && ['/SocialoraOfficial', '/SocialoraChat'].includes(u.pathname) && !u.searchRaw) {
    htmlOut += escHtml(m[0]);
    plainClean += m[0];
  }
  last = m.index + m[0].length;
}
htmlOut += escHtml(text.slice(last));
plainClean = (plainClean + text.slice(last)).replace(/\s+([.,!?])/g, '$1').trim();
htmlOut = htmlOut.trim();

if (sd.repliedTexts.some((prev) => prev.toLowerCase() === plainClean.toLowerCase())) {
  htmlOut += ' Let us know your platform and goal for more tailored tips.';
  plainClean += ' Let us know your platform and goal for more tailored tips.';
}

return [{
  json: {
    route: 'ai',
    update_id: aiSource.update_id,
    chat_id: aiSource.chat_id,
    reply_to_message_id: Number(aiSource.reply_to_message_id),
    htmlText: htmlOut,
    plainText: plainClean,
  }
}];

const tgRes = $input.first()?.json || {};
const ai = $('İnsanlaştırma, UTM & Güvenlik Doğrulaması').first()?.json || {};
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.inbox)) sd.inbox = [];
if (!Array.isArray(sd.repliedTexts)) sd.repliedTexts = [];

const msgId = tgRes?.result?.message_id ?? tgRes?.message_id ?? null;
const nowEpoch = Math.floor(Date.now() / 1000);

if (ai.update_id) {
  const row = sd.inbox.find((x) => x.update_id === ai.update_id);
  if (row) {
    row.status = 'replied';
    row.replyMessageId = msgId;
    row.repliedAt = nowEpoch;
  }
}
if (ai.plainText) {
  sd.repliedTexts.push(ai.plainText);
  if (sd.repliedTexts.length > 100) sd.repliedTexts = sd.repliedTexts.slice(-100);
}

return [{ json: { status: 'ai_replied', update_id: ai.update_id || null, reply_message_id: msgId, repliedAt: nowEpoch } }];

const src = $('Gelen Kutusu & Yönlendirme').all().find((i) => i.json?.route === 'ai')?.json;
if (!src) return [];

const sd = $getWorkflowStaticData('global');
const nowSec = Math.floor(Date.now() / 1000);
const disc = $input.first()?.json || {};
const rawModels = Array.isArray(disc.models) ? disc.models : [];
let candidates = [];
if (rawModels.length > 0) {
  candidates = rawModels
    .filter((m) => {
      const name = String(m.name || '').replace(/^models\//, '');
      const methods = Array.isArray(m.supportedGenerationMethods) ? m.supportedGenerationMethods : [];
      return name.includes('flash')
        && methods.includes('generateContent')
        && !/(image|tts|live|audio|preview|exp|thinking|robotics|computer|embedding)/i.test(name);
    })
    .map((m) => String(m.name || '').replace(/^models\//, ''));
  candidates.sort((a, b) => {
    const va = parseFloat((a.match(/gemini-(\d+(?:\.\d+)?)/) || [0, 0])[1]) || 0;
    const vb = parseFloat((b.match(/gemini-(\d+(?:\.\d+)?)/) || [0, 0])[1]) || 0;
    if (vb !== va) return vb - va;
    const la = a.includes('lite') ? 1 : 0;
    const lb = b.includes('lite') ? 1 : 0;
    if (la !== lb) return la - lb;
    return a.length - b.length;
  });
  if (candidates.length > 0) {
    sd.cachedModels = candidates;
    sd.modelsCachedAt = nowSec;
  }
} else if (Array.isArray(sd.cachedModels) && sd.cachedModels.length > 0) {
  candidates = sd.cachedModels;
}

const defaults = ['gemini-2.5-flash-lite', 'gemini-2.5-flash', 'gemini-3.5-flash-lite', 'gemini-flash-lite-latest'];
const ordered = [...new Set([...candidates, ...defaults])];
const primaryModel = ordered.find((n) => n === 'gemini-3.5-flash-lite')
  || ordered.find((n) => n === 'gemini-3.6-flash')
  || ordered[0];
const fallbackModel = ordered.find((n) => n === 'gemini-2.5-flash-lite')
  || ordered.find((n) => n === 'gemini-2.5-flash')
  || ordered.find((n) => n !== primaryModel)
  || primaryModel;

const userPrompt = 'Recent group conversation context:\n'
  + (src.contextLines || '(no prior context)')
  + '\n\nA member (@' + src.sender + ') just asked:\n"' + src.userText + '"\n\nWrite ONLY the direct plain-text reply.';

const buildBody = (model) => {
  const genCfg = { temperature: 0.7, topP: 0.9, maxOutputTokens: 700 };
  if (String(model).includes('2.5')) genCfg.thinkingConfig = { thinkingBudget: 0 };
  return {
    system_instruction: { parts: [{ text: "You are a helpful, knowledgeable team member at Socialora (getsocialora.com) helping creators in @SocialoraChat.\nSocialora provides Instagram, TikTok, YouTube, X and Telegram followers, views, likes, watch time and subscribers services, plus 50+ free creator diagnostic tools.\n\nVerified URLs (include AT MOST ONE URL and ONLY if directly useful):\n- All Services / Order: https://www.getsocialora.com/order\n- Instagram Followers, Views & Auto Likes (USA/Spanish/Arabic/Brazilian, 365-day refill options): https://www.getsocialora.com/instagram\n- TikTok Followers, Auto Likes & Auto Views: https://www.getsocialora.com/tiktok\n- YouTube Views, Watch Time & Subscribers: https://www.getsocialora.com/youtube\n- X (Twitter) Followers & Views: https://www.getsocialora.com/x\n- Telegram Members & Premium Subscribers: https://www.getsocialora.com/telegram\n- Free Instagram Views trial: https://www.getsocialora.com/free-instagram-views\n- TikTok Shadowban Checker: https://www.getsocialora.com/tools/tiktok-shadowban-checker\n- Instagram Shadowban Checker: https://www.getsocialora.com/tools/instagram-shadowban-checker\n- Who Viewed My Instagram Profile: https://www.getsocialora.com/tools/who-viewed-my-instagram-profile\n- Track Order Status: https://www.getsocialora.com/track\n- FAQ: https://www.getsocialora.com/faq\n- All Free Tools: https://www.getsocialora.com/tools\n\nVerified facts (never invent prices, delivery times or guarantees):\n- No password is ever needed; only public link or username.\n- If someone asks for free followers or free likes, be upfront that follower/like services are paid (/instagram or /order), while Free Instagram Views trial (/free-instagram-views) and 50+ creator tools (/tools) are free.\n- Payments: crypto checkout, plus manual USDT (TRC20, BNB Smart Chain, Solana), USDC (ERC20), or Bitcoin.\n- Private order help: /track page or info@getsocialora.com. Never ask for order IDs, emails or payment screenshots in public chat.\n\nHOW TO WRITE:\n- Plain text like a real person typing in chat. ZERO emojis, no markdown, no bullets (U+2022), no bold, no hashtags, no em-dashes (U+2014), no en-dashes (U+2013).\n- No greeting formula or praise ('Hey there', 'Great question', 'Happy to help').\n- Never say '100% safe', 'never drops', 'guaranteed followers', 'game-changer', 'elevate', 'unlock', 'skyrocket', 'delve', 'realm', 'unleash', 'tapestry', 'let us dive in', or 'in conclusion'.\n- Always write strictly in clear, natural English ONLY (1 to 3 short sentences). Never reply in Turkish or any non-English language even if a message is written in another language." }] },
    contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
    generationConfig: genCfg
  };
};

return [{
  json: {
    primaryModel,
    fallbackModel,
    cacheUsed: rawModels.length === 0,
    discovered: candidates.slice(0, 6),
    requestBody: buildBody(primaryModel),
    fallbackBody: buildBody(fallbackModel),
  }
}];
